// WF1 runtime configuration.
// NON-SECRET values only. API keys and OAuth tokens live in n8n Credentials, never here.
// Only sheetId must be changed before first run.
const config = {
  emailUrl: 'https://postman-echo.com/post',   // stub SMTP endpoint (echoes the request so the body is visible in the execution log)
  smsUrl:   'https://postman-echo.com/post',   // stub for Respond.io / WhatsApp Business API
  sheetId:  'YOUR_GOOGLE_SHEET_ID',
  sheetTab: 'Onboarding_Audit',
  senderEmail: 'onboarding@example.com',
  senderName:  '<COMPANY> (demo)',
  dedupeWindowDays: 7,
  demoMode: true
};
return $input.all().map(i => ({ json: { ...i.json, config }, binary: i.binary }));

// Single validation gate. Returns a structured result, never throws, so the
// workflow cannot crash on a bad payload and the caller always gets an answer.
const item = $input.first();
const config = item.json.config;
const correlation_id = 'WF1-' + $execution.id;
const received_at = new Date().toISOString();
const base = { config, correlation_id, received_at };

function fail(httpCode, status, message, extra) {
  return [{ json: { ...base, valid: false, httpCode, contractor_id: null, outcome: status,
    response: Object.assign({ status, message, correlation_id }, extra || {}) } }];
}

// 1. Recover the body in whichever shape the webhook delivered it.
let raw = null, parsed = null;
try {
  if (item.binary && item.binary.data && item.binary.data.data) {
    raw = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
  } else if (typeof item.json.body === 'string') {
    raw = item.json.body;
  }
  if (raw !== null) {
    if (raw.length > 16384) return fail(413, 'payload_too_large', 'Request body exceeds the 16 KiB limit for this endpoint.');
    parsed = JSON.parse(raw);
  } else {
    parsed = item.json.body;
  }
} catch (err) {
  return fail(400, 'invalid_json', 'Request body is not valid JSON. Nothing was processed.');
}

if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
  return fail(422, 'invalid_payload', 'Request body must be a JSON object.');
}

// 2. Field level validation. Every problem is collected, not just the first one,
// so the caller can fix the whole payload in one round trip.
const REQUIRED = ['contractor_id','name','email','phone','contract_type','start_date','agency_name'];
const CONTRACT_TYPES = ['PAYE','Umbrella','Ltd'];
const errors = [];
const c = {};

for (const f of REQUIRED) {
  let v = parsed[f];
  if (typeof v === 'number' && Number.isSafeInteger(v)) v = String(v);
  if (typeof v !== 'string' || v.trim() === '') { errors.push({ field: f, code: 'MISSING_OR_EMPTY' }); continue; }
  v = v.trim();
  if (v.length > 256) { errors.push({ field: f, code: 'TOO_LONG', max: 256 }); continue; }
  c[f] = v;
}

// Explicit boolean check. "false" as a string is truthy in JS and is a real
// integration bug, so it is rejected rather than silently treated as verified.
if (typeof parsed.documents_verified !== 'boolean') {
  errors.push({ field: 'documents_verified', code: 'MUST_BE_BOOLEAN', received: typeof parsed.documents_verified });
} else {
  c.documents_verified = parsed.documents_verified;
}

if (c.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(c.email)) {
  errors.push({ field: 'email', code: 'INVALID_FORMAT' });
}

if (c.phone) {
  const digits = c.phone.replace(/[\s()\-]/g, '');
  if (!/^\+?[0-9]{7,15}$/.test(digits)) errors.push({ field: 'phone', code: 'INVALID_FORMAT' });
  else c.phone = digits;
}

if (c.contract_type && !CONTRACT_TYPES.includes(c.contract_type)) {
  errors.push({ field: 'contract_type', code: 'INVALID_VALUE', allowed: CONTRACT_TYPES });
}

if (c.start_date) {
  const d = new Date(c.start_date + 'T00:00:00Z');
  const wellFormed = /^\d{4}-\d{2}-\d{2}$/.test(c.start_date);
  if (!wellFormed || !Number.isFinite(d.getTime()) || d.toISOString().slice(0,10) !== c.start_date) {
    errors.push({ field: 'start_date', code: 'EXPECTED_YYYY_MM_DD' });
  }
}

if (errors.length) {
  return [{ json: { ...base, valid: false, httpCode: 422,
    contractor_id: c.contractor_id || null, outcome: 'validation_failed', payload: c,
    response: { status: 'validation_failed',
      message: errors.length + ' field(s) failed validation. No notification was sent.',
      correlation_id, errors } } }];
}

// 3. Derive the routing decision and the idempotency key once, here, so every
// downstream node agrees on them.
const event_kind = c.documents_verified ? 'welcome' : 'documents_outstanding';
const idempotency_key = [c.contractor_id, c.agency_name.toLowerCase(), c.start_date, event_kind].join('|');

return [{ json: { ...base, valid: true, payload: c, contractor_id: c.contractor_id, event_kind, idempotency_key } }];

// Idempotency claim.
// At ~20k onboarding events a week a webhook retry storm would otherwise message
// thousands of contractors twice. Workflow static data gives us deduplication with
// zero external dependencies, which keeps this workflow importable and runnable as is.
//
// HONEST LIMIT: static data is written when the execution finishes, so this
// deduplicates sequential retries (the common case) but is NOT a distributed lock.
// In production against SQL Server this becomes a single atomic claim statement
// (MERGE with HOLDLOCK, or INSERT into a unique index and catch the violation).
const e = $input.first().json;
const store = $getWorkflowStaticData('global');
store.events = store.events || {};

const windowMs = (e.config.dedupeWindowDays || 7) * 86400000;
const now = Date.now();
for (const k of Object.keys(store.events)) {
  if (now - (store.events[k].claimed_at || 0) > windowMs) delete store.events[k];
}

const prior = store.events[e.idempotency_key];
if (prior) {
  return [{ json: { ...e, is_new: false, httpCode: 200, outcome: 'duplicate_suppressed',
    response: { status: 'duplicate_suppressed',
      message: 'This onboarding event was already processed. No duplicate notification was sent.',
      correlation_id: e.correlation_id, contractor_id: e.contractor_id,
      original_correlation_id: prior.correlation_id, original_outcome: prior.outcome } } }];
}

store.events[e.idempotency_key] = { claimed_at: now, correlation_id: e.correlation_id, outcome: 'processing' };
return [{ json: { ...e, is_new: true } }];

const e = $input.first().json, p = e.payload;
const tag = e.config.demoMode ? '[DEMO] ' : '';

const subject = tag + 'Welcome, your ' + p.contract_type + ' engagement starts ' + p.start_date;
const body = [
  'Hello ' + p.name + ',',
  '',
  'Your onboarding documents have been verified and your engagement is confirmed.',
  '',
  'Contract type: ' + p.contract_type,
  'Start date:    ' + p.start_date,
  'Agency:        ' + p.agency_name,
  '',
  'If any of the above is wrong, contact your agency before your start date.',
  '',
  'Reference: ' + e.correlation_id
].join('\n');

const sms = tag + 'Hi ' + p.name + ', your documents are verified. Your ' + p.contract_type +
  ' engagement starts ' + p.start_date + '. Check your email for the details.';

return [{ json: { ...e, template: 'welcome', channels: {},
  emailBody: {
    personalizations: [{ to: [{ email: p.email, name: p.name }] }],
    from: { email: e.config.senderEmail, name: e.config.senderName },
    subject,
    content: [{ type: 'text/plain', value: body }]
  },
  smsBody: { to: p.phone, body: sms } } }];

const e = $input.first().json, p = e.payload;
const tag = e.config.demoMode ? '[DEMO] ' : '';

const subject = tag + 'Action needed, documents outstanding for your ' + p.start_date + ' start';
const body = [
  'Hello ' + p.name + ',',
  '',
  'We cannot complete your onboarding yet because your documents are still outstanding.',
  '',
  'Contract type: ' + p.contract_type,
  'Start date:    ' + p.start_date,
  'Agency:        ' + p.agency_name,
  '',
  'Please contact ' + p.agency_name + ' using your existing trusted contact details to',
  'complete your documents. Your start date is at risk until this is done.',
  '',
  'Reference: ' + e.correlation_id
].join('\n');

const sms = tag + 'Hi ' + p.name + ', documents are still outstanding for your ' + p.start_date +
  ' start. Please check your email and contact ' + p.agency_name + '.';

return [{ json: { ...e, template: 'documents_outstanding', channels: {},
  emailBody: {
    personalizations: [{ to: [{ email: p.email, name: p.name }] }],
    from: { email: e.config.senderEmail, name: e.config.senderName },
    subject,
    content: [{ type: 'text/plain', value: body }]
  },
  smsBody: { to: p.phone, body: sms } } }];

// Classify the email attempt. Reached on BOTH the success and the error output of
// the HTTP node, so a transport failure is recorded rather than lost.
const e = $('Notification Ready').first().json;
const r = $input.first().json;

const status = Number(r.statusCode || 0);
const transportError = Boolean(r.error) || !status;
const accepted = !transportError && status >= 200 && status < 300;

// 2xx means ACCEPTED BY THE PROVIDER, not delivered to the human. 5xx and transport
// failures are 'uncertain' because the message may or may not have gone out.
const state = accepted ? 'accepted' : (transportError || status >= 500 ? 'uncertain' : 'rejected');

return [{ json: { ...e, channels: { ...e.channels, email: {
  state,
  http_status: status || null,
  reason: accepted ? null : (transportError ? 'TRANSPORT_ERROR' : 'HTTP_' + status),
  attempted_at: new Date().toISOString()
} } } }];

const e = $('Capture Email Outcome').first().json;
const r = $input.first().json;

const status = Number(r.statusCode || 0);
const transportError = Boolean(r.error) || !status;
const accepted = !transportError && status >= 200 && status < 300;
const state = accepted ? 'accepted' : (transportError || status >= 500 ? 'uncertain' : 'rejected');

return [{ json: { ...e, channels: { ...e.channels, sms: {
  state,
  http_status: status || null,
  reason: accepted ? null : (transportError ? 'TRANSPORT_ERROR' : 'HTTP_' + status),
  attempted_at: new Date().toISOString()
} } } }];

// Single place that decides the outcome, so the audit row and the HTTP response
// can never disagree with each other.
const e = $input.first().json;
const em = e.channels.email || { state: 'not_attempted' };
const sm = e.channels.sms   || { state: 'not_attempted' };

const both    = em.state === 'accepted' && sm.state === 'accepted';
const reached = em.state === 'accepted' || sm.state === 'accepted';

const outcome  = both ? e.event_kind + '_sent'
               : reached ? e.event_kind + '_sent_degraded'
               : 'delivery_failed';
const httpCode = both ? 200 : (reached ? 207 : 502);

const message = both
  ? 'Both channels accepted the notification.'
  : reached
    ? 'The contractor was reached on one channel. The other failed and is recorded below for review.'
    : 'No channel accepted the notification. Nothing was delivered and this event is safe to resubmit.';

// Close out the idempotency claim. If NOTHING was delivered we release the claim so
// a retry is not blocked by a send that never happened.
const store = $getWorkflowStaticData('global');
if (store.events && store.events[e.idempotency_key]) {
  if (reached) store.events[e.idempotency_key].outcome = outcome;
  else delete store.events[e.idempotency_key];
}

return [{ json: { ...e, outcome, httpCode, response: {
  status: outcome, message,
  correlation_id: e.correlation_id,
  contractor_id: e.contractor_id,
  event_kind: e.event_kind,
  channels: e.channels,
  demo_mode: e.config.demoMode
} } }];

// One audit row per event, on EVERY path: validation failure, duplicate, and delivery.
// Emits EXACTLY the ten sheet columns and nothing else. n8n's auto-mapping APPENDS a new
// column for any field it cannot match against a header, so carrying context through here
// would silently widen the audit sheet.
const e  = $input.first().json;
const p  = e.payload  || {};
const ch = e.channels || {};

return [{ json: {
  contractor_id:  e.contractor_id || p.contractor_id || '',
  timestamp:      new Date().toISOString(),
  outcome:        e.outcome || 'unknown',
  correlation_id: e.correlation_id || '',
  event_kind:     e.event_kind || '',
  contract_type:  p.contract_type || '',
  agency_name:    p.agency_name || '',
  email_state:    (ch.email && ch.email.state) || 'not_attempted',
  sms_state:      (ch.sms   && ch.sms.state)   || 'not_attempted',
  demo_mode:      e.config && e.config.demoMode ? 'true' : 'false'
} }];

// The outcome was decided on one of three mutually exclusive paths. Read it back from
// whichever of those nodes actually ran, most specific first.
function upstream() {
  for (const name of ['Decide Delivery Outcome', 'Claim Idempotency Key', 'Validate and Normalise']) {
    try {
      const j = $(name).first().json;
      if (j && j.httpCode && j.response) return j;
    } catch (err) { /* this node did not run on this path */ }
  }
  return null;
}

const ctx = upstream() || { httpCode: 500, response: {
  status: 'internal_error',
  message: 'The outcome could not be resolved. Inspect this execution before resubmitting.'
} };

const r = $input.first().json;
const logged = !r.error;
const response = { ...ctx.response, audit_logged: logged };

if (!logged) {
  // Say WHY the audit failed. An audit gap you cannot diagnose is barely better than no audit.
  const err = r.error;
  const detail = typeof err === 'string'
    ? err
    : (err && (err.message || err.description || err.reason)) || JSON.stringify(err);
  response.audit_warning = 'The notification outcome above is accurate, but the audit row could not be written to Google Sheets. Reconcile from the n8n execution log before trusting the sheet.';
  response.audit_error = String(detail).slice(0, 300);
}

return [{ json: { httpCode: ctx.httpCode, response } }];
